@pytest.mark.keep_ci_var
@pytest.mark.skipif(
    "CI" in os.environ and sys.platform == "linux" and sys.version_info >= (3, 14),
    reason="sometimes crashes on CI because of truncated outputs (#7022)",
)
@pytest.mark.parametrize("exit_on_timeout", [True, False])
def test_timeout_and_exit(pytester: Pytester, exit_on_timeout: bool) -> None:
    """Test option to force exit pytest process after a certain timeout."""
    pytester.makepyfile(
        """
    import os, time
    def test_long_sleep_and_raise():
        time.sleep(1 if "CI" in os.environ else 0.1)
        raise AssertionError(
            "This test should have been interrupted before reaching this point."
        )
    """
    )
    pytester.makeini(
        f"""
        [pytest]
        faulthandler_timeout = 0.01
        faulthandler_exit_on_timeout = {"true" if exit_on_timeout else "false"}
        """
    )
    result = pytester.runpytest_subprocess()
    tb_output = "most recent call first"
    result.stderr.fnmatch_lines([f"*{tb_output}*"])
    if exit_on_timeout:
        result.stdout.no_fnmatch_line("*1 failed*")
        result.stdout.no_fnmatch_line("*AssertionError*")
    else:
        result.stdout.fnmatch_lines(["*1 failed*"])
        result.stdout.fnmatch_lines(["*AssertionError*"])
    assert result.ret == 1

@pytest.hookimpl(wrapper=True, trylast=True)
def pytest_runtest_protocol(item: Item) -> Generator[None, object, object]:
    timeout = get_timeout_config_value(item.config)
    exit_on_timeout = get_exit_on_timeout_config_value(item.config)
    if timeout > 0:
        import faulthandler

        stderr = item.config.stash[fault_handler_stderr_fd_key]
        faulthandler.dump_traceback_later(timeout, file=stderr, exit=exit_on_timeout)
        try:
            return (yield)
        finally:
            faulthandler.cancel_dump_traceback_later()
    else:
        return (yield)

@pytest.mark.parametrize("op", [">=", "<="])
def test_dict_items_view_subset(self, op, pytester: Pytester) -> None:
    """dict.items() supports set-like comparisons; assert diff should show the missing items."""
    if op == ">=":
        pytester.makepyfile(
            """
            def test_hello():
                x = {"a": 1, "b": 2}
                y = {"a": 1, "b": 2, "c": 3}
                assert x.items() >= y.items()
        """
        )
    else:
        pytester.makepyfile(
            """
            def test_hello():
                x = {"a": 1, "b": 2, "c": 3}
                y = {"a": 1, "b": 2}
                assert x.items() <= y.items()
        """
        )
    result = pytester.runpytest()
    side = "right" if op == ">=" else "left"
    result.stdout.fnmatch_lines(
        [
            "*def test_hello():*",
            f"*assert x.items() {op} y.items()*",
            f"*E*Extra items in the {side} set:*",
            "*E*('c', 3)*",
        ]
    )

def _warn_on_inexact_decimal_tolerance(
    expected: object,
    rel: float | Decimal | timedelta | None,
    abs: float | Decimal | timedelta | None,
) -> None:
    """Warn when a float tolerance is used for a Decimal comparison.

    A float tolerance is converted with ``Decimal.from_float()``, which is
    exact and therefore keeps the float's full binary expansion: ``rel=0.01``
    really means a tolerance of ``0.010000000000000000208...``. That is wider
    than the ``0.01`` that was written, which defeats the point of comparing
    Decimals in the first place.

    Only floats that cannot be represented exactly are worth warning about;
    ``0.5`` and friends survive the conversion unchanged, as do ints.
    """
    inexact = [
        (name, value)
        for name, value in (("rel", rel), ("abs", abs))
        if type(value) is float and Decimal.from_float(value) != Decimal(repr(value))
    ]
    if not inexact or not _contains_decimal(expected):
        return
    for name, value in inexact:
        warnings.warn(
            PytestApproxDecimalToleranceWarning(
                f"{name}={value!r} cannot be represented exactly as a Decimal "
                f"and was widened to {Decimal.from_float(value)}.\n"
                f"Pass {name}=Decimal({str(value)!r}) to compare against the "
                f"tolerance you wrote."
            ),
            stacklevel=3,

